/**
 * End-to-end guards for the query shapes the SPARQL compliance suites use that used to fail LMDB planning with a
 * {@link NullPointerException}: {@code VALUES ... UNDEF} rows (a {@code null} binding value), a dataset naming the
 * store default graph with {@code null}, and a variable predicate combined with a constant object.
 */
class LmdbPlanningNullValueRegressionTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI P1 = VF.createIRI("urn:p1");
	private static final IRI P2 = VF.createIRI("urn:p2");
	private static final IRI Q = VF.createIRI("urn:q");
	private static final IRI A = VF.createIRI("urn:a");
	private static final IRI B = VF.createIRI("urn:b");
	private static final IRI C = VF.createIRI("urn:c");
	private static final IRI D = VF.createIRI("urn:d");
	private static final IRI G = VF.createIRI("urn:g");

	@Test
	void valuesWithUndefRowsEvaluatesColdAndFromTheCache(@TempDir File dataDir) {
		String query = "SELECT * WHERE { VALUES (?x ?y) { (UNDEF <urn:a>) (<urn:b> UNDEF) } ?s <urn:p> ?x }";
		Set<String> expected = Set.of("urn:a|urn:b|urn:a", "urn:a|urn:b|UNBOUND");
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, B);
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			List<BindingSet> coldBindings = bindings(connection, query, null);
			assertEquals(expected, rows(coldBindings, "s", "x", "y"), "cold run");
			assertUndefCellsUnbound(coldBindings);

			List<BindingSet> warmBindings = bindings(connection, query, null);
			assertEquals(expected, rows(warmBindings, "s", "x", "y"), "warm run must equal the cold run");
			assertUndefCellsUnbound(warmBindings);

			TupleExpr plan = explain(connection, query, null);
			assertEquals("true", plan.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"),
					"a VALUES ... UNDEF plan must be retainable in the pipeline plan cache");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void singleColumnValuesWithUndefRowEvaluatesTwice(@TempDir File dataDir) {
		String query = "SELECT ?s ?x WHERE { VALUES ?x { UNDEF <urn:a> } ?s <urn:p> ?x }";
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, B);
			connection.add(C, P, A);
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			Set<String> expected = Set.of("urn:a|urn:b", "urn:c|urn:a");
			assertEquals(new TreeSet<>(expected), rows(bindings(connection, query, null), "s", "x"));
			assertEquals(new TreeSet<>(expected), rows(bindings(connection, query, null), "s", "x"));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void updateWithNullDefaultGraphDatasetInsertsRows(@TempDir File dataDir) {
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, B);
			connection.add(C, P, D, G);
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			Update update = connection.prepareUpdate("INSERT { ?s <urn:q> ?o } WHERE { ?s <urn:p> ?o }");
			update.setDataset(nullGraphDataset());
			update.execute();
			update.execute();

			assertEquals(Set.of("urn:a|urn:b"),
					rows(bindings(connection, "SELECT ?s ?o WHERE { ?s <urn:q> ?o }", null), "s", "o"),
					"the null default graph restricts WHERE to the null context; the named graph row is excluded");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void queryWithNullDefaultGraphDatasetSeesOnlyTheNullContext(@TempDir File dataDir) {
		String query = "SELECT ?s ?o WHERE { ?s <urn:p> ?o }";
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P, B);
			connection.add(C, P, D, G);
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			assertEquals(Set.of("urn:a|urn:b", "urn:c|urn:d"), rows(bindings(connection, query, null), "s", "o"),
					"no dataset reads every context");
			assertEquals(Set.of("urn:a|urn:b"), rows(bindings(connection, query, nullGraphDataset()), "s", "o"),
					"cold: the null default graph excludes named graphs");
			assertEquals(Set.of("urn:a|urn:b"), rows(bindings(connection, query, nullGraphDataset()), "s", "o"),
					"warm: the null default graph excludes named graphs");
			assertEquals(Set.of("urn:a|urn:b", "urn:c|urn:d"), rows(bindings(connection, query, null), "s", "o"),
					"the unrestricted plan must not be confused with the restricted one");
			TupleExpr plan = explain(connection, query, nullGraphDataset());
			assertEquals("true", plan.getStringMetricPlanned("optimizer.datasetRestricted"),
					"a {null} default graph is a restricted dataset for the planner");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void variablePredicateWithConstantObjectEvaluates(@TempDir File dataDir) {
		String filtered = "SELECT ?s ?p WHERE { ?s ?p <urn:b> FILTER(?p != <urn:x>) }";
		String path = "SELECT ?s WHERE { ?s <urn:p1>+ <urn:b> }";
		SailRepository repository = repository(dataDir);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(A, P1, B);
			connection.add(A, P2, C);
			((LmdbStore) repository.getSail()).rebuildFrontierStatistics();

			assertEquals(Set.of("urn:a|urn:p1"), rows(bindings(connection, filtered, null), "s", "p"));
			assertEquals(Set.of("urn:a|urn:p1"), rows(bindings(connection, filtered, null), "s", "p"));
			assertEquals(Set.of("urn:a"), rows(bindings(connection, path, null), "s"));
			assertEquals(Set.of("urn:a"), rows(bindings(connection, path, null), "s"));
		} finally {
			repository.shutDown();
		}
	}

	private static void assertUndefCellsUnbound(List<BindingSet> bindings) {
		for (BindingSet bindingSet : bindings) {
			if (bindingSet.getValue("y") == null) {
				assertFalse(bindingSet.hasBinding("y"), "an UNDEF cell must not be reported as bound");
			} else {
				assertTrue(bindingSet.hasBinding("y"));
			}
		}
	}

	private static Dataset nullGraphDataset() {
		SimpleDataset dataset = new SimpleDataset();
		dataset.addDefaultGraph(null);
		dataset.addDefaultRemoveGraph(null);
		dataset.setDefaultInsertGraph(null);
		return dataset;
	}

	private static SailRepository repository(File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
		return repository;
	}

	private static List<BindingSet> bindings(RepositoryConnection connection, String query, Dataset dataset) {
		TupleQuery tupleQuery = connection.prepareTupleQuery(query);
		if (dataset != null) {
			tupleQuery.setDataset(dataset);
		}
		List<BindingSet> bindings = new ArrayList<>();
		try (TupleQueryResult result = tupleQuery.evaluate()) {
			for (BindingSet bindingSet : result) {
				bindings.add(bindingSet);
			}
		}
		return bindings;
	}

	private static Set<String> rows(List<BindingSet> bindings, String... names) {
		Set<String> rows = new TreeSet<>();
		for (BindingSet bindingSet : bindings) {
			StringBuilder row = new StringBuilder();
			for (int index = 0; index < names.length; index++) {
				if (index > 0) {
					row.append('|');
				}
				row.append(bindingSet.getValue(names[index]) == null ? "UNBOUND"
						: bindingSet.getValue(names[index]).stringValue());
			}
			rows.add(row.toString());
		}
		return rows;
	}

	private static TupleExpr explain(RepositoryConnection connection, String query, Dataset dataset) {
		TupleQuery tupleQuery = connection.prepareTupleQuery(query);
		if (dataset != null) {
			tupleQuery.setDataset(dataset);
		}
		return (TupleExpr) tupleQuery.explain(Explanation.Level.Optimized).tupleExpr();
	}
}
